 */
public object FfiConverterTypeArrivalListener: FfiConverter<ArrivalListener, Long> {
    internal val handleMap = UniffiHandleMap<ArrivalListener>()

    override fun lower(value: ArrivalListener): Long {
        if (value is ArrivalListenerImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): ArrivalListener {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return ArrivalListenerImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): ArrivalListener {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: ArrivalListener) = 8UL

    override fun write(value: ArrivalListener, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


