/**
 * A blob stream: files and other bytes, each kept whole.
 */
public interface BlobsInterface {

    /**
     * The SHA-256 of a blob's plaintext, computed on this device; none
     * while it cannot read the blob whole. It fetches nothing.
     */
    suspend fun `contentHash`(`id`: kotlin.String): kotlin.ByteArray?

    /**
     * A blob's bytes, or none while this device does not hold them whole.
     */
    suspend fun `get`(`id`: kotlin.String): kotlin.ByteArray?

    /**
     * The stream's ID.
     */
    fun `id`(): kotlin.String

    /**
     * Follows where a blob's bytes stand: the current status, then each
     * change.
     */
    fun `observeStatus`(`id`: kotlin.String, `listener`: BlobStatusListener): Subscription

    /**
     * Puts a blob, with a name if given; returns its ID.
     */
    suspend fun `put`(`name`: kotlin.String?, `bytes`: kotlin.ByteArray): kotlin.String

    /**
     * Puts a blob from the file at `path`, with a name if given; returns
     * its ID. The file is read twice, once for the blob's ID and once to
     * seal it a chunk at a time, so a put holds a few chunks in memory
     * whatever the file's size. The file must not change during the put:
     * one that does fails `Changed`, and nothing is kept.
     */
    suspend fun `putFile`(`name`: kotlin.String?, `path`: kotlin.String, `listener`: PutProgressListener?): kotlin.String

    /**
     * Where a blob's bytes stand on this device.
     */
    suspend fun `status`(`id`: kotlin.String): BlobStatus

    companion object
}

