     * `true` once every change this device made in the space is
     * acknowledged; `false` while any waits.
     */override fun `durable`(`durable`: kotlin.Boolean)
        =
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_frasil_uniffi_fn_method_durablelistener_durable(
        it,
        FfiConverterBoolean.lower(`durable`),_status)
}
    }




    /**
     * The read failed.
     */override fun `failed`(`message`: kotlin.String)
        =
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_frasil_uniffi_fn_method_durablelistener_failed(
        it,
        FfiConverterString.lower(`message`),_status)
}
    }










