 */
public object FfiConverterTypeDurableListener: FfiConverter<DurableListener, Long> {
    internal val handleMap = UniffiHandleMap<DurableListener>()

    override fun lower(value: DurableListener): Long {
        if (value is DurableListenerImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): DurableListener {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return DurableListenerImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): DurableListener {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: DurableListener) = 8UL

    override fun write(value: DurableListener, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


