/**
 * Something a device holds for the first time.
 */
sealed class Arrival {

    /**
     * A space: its streams follow.
     */
    data class Space(
        /**
         * The space's ID.
         */
        val `space`: kotlin.String) : Arrival()

    {


        companion object
    }

    /**
     * A stream of a space.
     */
    data class Stream(
        /**
         * The space's ID.
         */
        val `space`: kotlin.String,
        /**
         * The stream's ID.
         */
        val `stream`: kotlin.String) : Arrival()

    {


        companion object
    }








    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeArrival : FfiConverterRustBuffer<Arrival>{
    override fun read(buf: ByteBuffer): Arrival {
        return when(buf.getInt()) {
            1 -> Arrival.Space(
                FfiConverterString.read(buf),
                )
            2 -> Arrival.Stream(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Arrival) = when(value) {
        is Arrival.Space -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`space`)
            )
        }
        is Arrival.Stream -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`space`)
                + FfiConverterString.allocationSize(value.`stream`)
            )
        }
    }

    override fun write(value: Arrival, buf: ByteBuffer) {
        when(value) {
            is Arrival.Space -> {
                buf.putInt(1)
                FfiConverterString.write(value.`space`, buf)
                Unit
            }
            is Arrival.Stream -> {
                buf.putInt(2)
                FfiConverterString.write(value.`space`, buf)
                FfiConverterString.write(value.`stream`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * Where a blob's bytes stand on this device.
 */
sealed class BlobStatus {

    /**
     * The device holds the bytes whole.
     */
    object Readable : BlobStatus()


    /**
     * A peer or member is sending them.
     */
    data class Fetching(
        /**
         * The bytes fetched so far, by share of the object.
         */
        val `done`: kotlin.ULong,
        /**
         * The blob's size.
         */
        val `total`: kotlin.ULong) : BlobStatus()

    {


        companion object
    }

    /**
     * Nothing is sending them now: no peer or member is connected, or
     * they have not been asked for.
     */
    object Missing : BlobStatus()


    /**
     * The key they are sealed under has not reached this device yet.
     */
    object KeysPending : BlobStatus()


    /**
     * A held file changed or is gone; peers and members still have them.
     */
    object Withdrawn : BlobStatus()









    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeBlobStatus : FfiConverterRustBuffer<BlobStatus>{
    override fun read(buf: ByteBuffer): BlobStatus {
        return when(buf.getInt()) {
            1 -> BlobStatus.Readable
            2 -> BlobStatus.Fetching(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            3 -> BlobStatus.Missing
            4 -> BlobStatus.KeysPending
            5 -> BlobStatus.Withdrawn
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: BlobStatus) = when(value) {
        is BlobStatus.Readable -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is BlobStatus.Fetching -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`done`)
                + FfiConverterULong.allocationSize(value.`total`)
            )
        }
        is BlobStatus.Missing -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is BlobStatus.KeysPending -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is BlobStatus.Withdrawn -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: BlobStatus, buf: ByteBuffer) {
        when(value) {
            is BlobStatus.Readable -> {
                buf.putInt(1)
                Unit
            }
            is BlobStatus.Fetching -> {
                buf.putInt(2)
                FfiConverterULong.write(value.`done`, buf)
                FfiConverterULong.write(value.`total`, buf)
                Unit
            }
            is BlobStatus.Missing -> {
                buf.putInt(3)
                Unit
            }
            is BlobStatus.KeysPending -> {
                buf.putInt(4)
                Unit
            }
            is BlobStatus.Withdrawn -> {
                buf.putInt(5)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





