/**
 * What a device's deposits in device mailboxes report: welcomes, leave
 * requests and a person's list (transport.md, "A sender keeps what was
 * refused"; ext-deposit-tokens.md).
 */
sealed class DepositReport {

    /**
     * The peer answered `busy` or `rate_limited`, or was not reached: the
     * device keeps the item and sends it again by itself, after a random
     * wait that grows to an hour, for up to 30 days.
     */
    data class Delayed(
        /**
         * The peer's origin.
         */
        val `peer`: kotlin.String,
        /**
         * The peer's reason code, or why it was not reached.
         */
        val `reason`: kotlin.String) : DepositReport()

    {


        companion object
    }

    /**
     * A delayed deposit was accepted.
     */
    data class Delivered(
        /**
         * The peer's origin.
         */
        val `peer`: kotlin.String) : DepositReport()

    {


        companion object
    }

    /**
     * A deposit was given up: `expired` after 30 days, or the peer's
     * final refusal.
     */
    data class Undelivered(
        /**
         * The peer's origin.
         */
        val `peer`: kotlin.String,
        /**
         * `expired`, or the peer's reason code.
         */
        val `reason`: kotlin.String) : DepositReport()

    {


        companion object
    }

    /**
     * The device stopped drawing and spending deposit tokens at the peer:
     * `key_inconsistent` until `trust_deposit_keys`, or `bad_proof`, which
     * drops one batch. Deposits there go on without tokens.
     */
    data class PeerDistrusted(
        /**
         * The peer's origin.
         */
        val `peer`: kotlin.String,
        /**
         * `key_inconsistent` or `bad_proof`.
         */
        val `reason`: kotlin.String) : DepositReport()

    {


        companion object
    }








    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeDepositReport : FfiConverterRustBuffer<DepositReport>{
    override fun read(buf: ByteBuffer): DepositReport {
        return when(buf.getInt()) {
            1 -> DepositReport.Delayed(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> DepositReport.Delivered(
                FfiConverterString.read(buf),
                )
            3 -> DepositReport.Undelivered(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> DepositReport.PeerDistrusted(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: DepositReport) = when(value) {
        is DepositReport.Delayed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peer`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
        is DepositReport.Delivered -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peer`)
            )
        }
        is DepositReport.Undelivered -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peer`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
        is DepositReport.PeerDistrusted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peer`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: DepositReport, buf: ByteBuffer) {
        when(value) {
            is DepositReport.Delayed -> {
                buf.putInt(1)
                FfiConverterString.write(value.`peer`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is DepositReport.Delivered -> {
                buf.putInt(2)
                FfiConverterString.write(value.`peer`, buf)
                Unit
            }
            is DepositReport.Undelivered -> {
                buf.putInt(3)
                FfiConverterString.write(value.`peer`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is DepositReport.PeerDistrusted -> {
                buf.putInt(4)
                FfiConverterString.write(value.`peer`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * A failure, with `frasil`'s description of it.
 */
sealed class FrasilException: kotlin.Exception() {

    /**
     * The call failed.
     */
    class Failed(

        /**
         * What went wrong, and what to do.
         */
        val `reason`: kotlin.String
        ) : FrasilException() {
        override val message
            get() = "reason=${ `reason` }"
    }





    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FrasilException> {
        override fun lift(error_buf: RustBuffer.ByValue): FrasilException = FfiConverterTypeFrasilError.lift(error_buf)
    }


}

/**
 * @suppress
 */
public object FfiConverterTypeFrasilError : FfiConverterRustBuffer<FrasilException> {
    override fun read(buf: ByteBuffer): FrasilException {


        return when(buf.getInt()) {
            1 -> FrasilException.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FrasilException): ULong {
        return when(value) {
            is FrasilException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: FrasilException, buf: ByteBuffer) {
        when(value) {
            is FrasilException.Failed -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * What a late membership change did.
 */

enum class LateChangeKind {

    /**
     * It admitted a member.
     */
    GRANT,
    /**
     * It changed a member's level or capabilities.
     */
    CHANGE,
    /**
     * It removed a member.
     */
    REMOVE,
    /**
     * Another change.
     */
    OTHER;




    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeLateChangeKind: FfiConverterRustBuffer<LateChangeKind> {
    override fun read(buf: ByteBuffer) = try {
        LateChangeKind.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: LateChangeKind) = 4UL

    override fun write(value: LateChangeKind, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





/**
 * What a device detects of the peers and members it syncs with
 * (units.md, 3.13 "Detected loss", "Head statements").
 */
sealed class LossReport {

    /**
     * A peer served less of a space than this device knows of
     * (`Withheld`): it left out units a stream's listing should name,
     * events of a state it served before, or a member's head statement's
     * heads that the member then supplied, when the peer had acknowledged
     * them or still lacked them after `withholding_grace`. The device
     * fetches what it lacks from other replicas.
     */
    data class Withheld(
        /**
         * The space's ID.
         */
        val `space`: kotlin.String) : LossReport()

    {


        companion object
    }

    /**
     * A peer, or in a space with no always-on peer the member `member`,
     * no longer holds events it acknowledged (`RolledBack`). This
     * device's own events among them count as not durable again, and are
     * offered again on every connection.
     */
    data class RolledBack(
        /**
         * The space's ID.
         */
        val `space`: kotlin.String,
        /**
         * The member's ID, when a member acknowledged; none for a peer.
         */
        val `member`: kotlin.String?) : LossReport()

    {


        companion object
    }

    /**
     * A member's head statement named events that member could not
     * supply when asked (`BadStatement`): the statement is dropped.
     */
    data class BadStatement(
        /**
         * The space's ID.
         */
        val `space`: kotlin.String,
        /**
         * The ID of the member that made it.
         */
        val `member`: kotlin.String) : LossReport()

    {


        companion object
    }








    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeLossReport : FfiConverterRustBuffer<LossReport>{
    override fun read(buf: ByteBuffer): LossReport {
        return when(buf.getInt()) {
            1 -> LossReport.Withheld(
                FfiConverterString.read(buf),
                )
            2 -> LossReport.RolledBack(
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            3 -> LossReport.BadStatement(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LossReport) = when(value) {
        is LossReport.Withheld -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`space`)
            )
        }
        is LossReport.RolledBack -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`space`)
                + FfiConverterOptionalString.allocationSize(value.`member`)
            )
        }
        is LossReport.BadStatement -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`space`)
                + FfiConverterString.allocationSize(value.`member`)
            )
        }
    }

    override fun write(value: LossReport, buf: ByteBuffer) {
        when(value) {
            is LossReport.Withheld -> {
                buf.putInt(1)
                FfiConverterString.write(value.`space`, buf)
                Unit
            }
            is LossReport.RolledBack -> {
                buf.putInt(2)
                FfiConverterString.write(value.`space`, buf)
                FfiConverterOptionalString.write(value.`member`, buf)
                Unit
            }
            is LossReport.BadStatement -> {
                buf.putInt(3)
                FfiConverterString.write(value.`space`, buf)
                FfiConverterString.write(value.`member`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






/**
 * @suppress
 */
public object FfiConverterOptionalUByte: FfiConverterRustBuffer<kotlin.UByte?> {
    override fun read(buf: ByteBuffer): kotlin.UByte? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterUByte.read(buf)
    }

    override fun allocationSize(value: kotlin.UByte?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterUByte.allocationSize(value)
        }
    }

    override fun write(value: kotlin.UByte?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterUByte.write(value, buf)
        }
    }
}




